import{_ as o,l,o as e,c as n,v as i,p as s,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"差分隐私","description":"","frontmatter":{"title":"差分隐私","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/differential-privacy.md","filePath":"cs/differential-privacy.md","lastUpdated":1789023840000}'),p={name:"cs/differential-privacy.md"};function f(_,a,m,u,E,A){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="差分隐私" tabindex="-1">差分隐私 <a class="header-anchor" href="#差分隐私" aria-label="Permalink to &quot;差分隐私&quot;">​</a></h1><div class="epigraph"><p>差分隐私给发布机制一张证明：任意一条记录在或不在，对输出分布的影响有界。隐私损失可加，预算要记账。它不靠「匿名化感觉」。</p><footer>—— Dwork, McSherry, Nissim and Smith, Calibrating Noise to Sensitivity, TCC 2006；Dwork and Roth, *The Algorithmic Foundations of Differential Privacy*</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/container-escape">容器</a>结束系统硬件。隐私单元从可证明的发布机制起。缺口是<strong>查询输出仍可能认出个体</strong>。本课钉 ε-差分隐私，不重写密码学。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚合计数仍可差分攻击。DP：相邻数据集上输出不可区分到 e^ε。缺口是灵敏度、噪声、组合。</p><h3 id="不是加密" tabindex="-1">不是加密 <a class="header-anchor" href="#不是加密" aria-label="Permalink to &quot;不是加密&quot;">​</a></h3><p>DP 保护的是发布分布，数据在服务器仍可能明文计算——除非叠 MPC/同态。</p><p><span class="marginnote">DMNS 2006。k-匿名下一课是句法匿名，已被证明不够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拉普拉斯机制点名。会计：基本组合。下一课 k-匿名对照。</p>',12)),(e(),s(c,null,{default:t(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20SENS%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20SENS%20--%3E%20NOISE%5B%22%E6%A0%A1%E5%87%86%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NOISE%20--%3E%20OUT%5B%22%CE%B5%20%E5%8F%AF%E8%AF%81%E7%9A%84%E5%8F%91%E5%B8%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把隐私当预算。k-匿名下一课无这种预算语言。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 ε 选成口号。k-匿名下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隔离课之后，发布数据要另套合同。</li><li>DP：相邻集输出近，预算可加。</li><li>不是加密，也不是感觉匿名。</li><li>下一课 k-匿名。</li><li>出处：Dwork, McSherry, Nissim and Smith, 2006；Dwork and Roth。</li></ul>',8))])}const P=o(p,[["render",f]]);export{k as __pageData,P as default};
